/**
 * Static renders of the 3D sculptures (generated by `npm run render:visuals`
 * from each scene's still pose) and the hotspot positions inside each image.
 */
import type { HotspotMap, SceneKey } from '../../three/types';
import hotspots from './hotspots.json';
import prism1200 from './prism-square-1200.webp';
import prism640 from './prism-square-640.webp';
import ribbon1600 from './ribbon-card-1600.webp';
import ribbon880 from './ribbon-card-880.webp';
import ribbonWide1600 from './ribbon-wide-1600.webp';
import ribbonWide960 from './ribbon-wide-960.webp';
import ribbonSq1400 from './ribbon-square-1400.webp';
import ribbonSq800 from './ribbon-square-800.webp';
import constellation1200 from './constellation-card-1200.webp';
import constellation680 from './constellation-card-680.webp';
import constellationSq800 from './constellation-square-800.webp';
import graph1000 from './graph-card-1000.webp';
import graph560 from './graph-card-560.webp';

export interface ArtVariant {
  src: string;
  srcSet: string;
  width: number;
  height: number;
  hotspots: HotspotMap;
}

export interface Art {
  /** Default composition. */
  main: ArtVariant;
  /** Square composition for narrow screens (art-directed, not a crop). */
  narrow?: ArtVariant;
  /** Wide composition for case-study headers. */
  wide?: ArtVariant;
}

const hs = hotspots as Record<string, Record<string, HotspotMap>>;

export const art: Record<SceneKey, Art> = {
  prism: {
    main: { src: prism1200, srcSet: `${prism640} 640w, ${prism1200} 1200w`, width: 1200, height: 1200, hotspots: hs.prism.square },
  },
  ribbon: {
    main: { src: ribbon1600, srcSet: `${ribbon880} 880w, ${ribbon1600} 1600w`, width: 1600, height: 1200, hotspots: hs.ribbon.card },
    wide: { src: ribbonWide1600, srcSet: `${ribbonWide960} 960w, ${ribbonWide1600} 1600w`, width: 1600, height: 1000, hotspots: hs.ribbon.wide },
    narrow: { src: ribbonSq800, srcSet: `${ribbonSq800} 800w, ${ribbonSq1400} 1400w`, width: 800, height: 800, hotspots: hs.ribbon.square },
  },
  constellation: {
    main: {
      src: constellation1200,
      srcSet: `${constellation680} 680w, ${constellation1200} 1200w`,
      width: 1200,
      height: 750,
      hotspots: hs.constellation.card,
    },
    narrow: {
      src: constellationSq800,
      srcSet: `${constellationSq800} 800w`,
      width: 800,
      height: 800,
      hotspots: hs.constellation.square,
    },
  },
  graph: {
    main: { src: graph1000, srcSet: `${graph560} 560w, ${graph1000} 1000w`, width: 1000, height: 625, hotspots: hs.graph?.card ?? {} },
  },
};

/** Breakpoint at which the narrow (square) compositions are used. */
export const NARROW_MEDIA = '(max-width: 767px)';
